"use client";

import React, { useEffect, useRef, useState } from "react";
import { createRoot, Root } from "react-dom/client";

export interface ShieldCodeWidgetConfiguredPayload {
  is_enabled: boolean;
  masked_code: string;
  security_code: string;
  company_name: string;
  external_user_id: string;
  updated_at: string;
}

export interface ShieldCodeWidgetProps {
  /**
   * Short-lived HS256 JWT token (`eyJ...`) generated by the Partner Bank's backend
   * via `POST /api/v1/widget/session`.
   */
  clientSessionToken: string;
  /**
   * Optional ShieldCode SaaS API origin (defaults to the current ShieldCode origin).
   * All widget API calls hit this backend directly — never the Bank's backend.
   */
  apiBaseUrl?: string;
  /**
   * Optional initial code value for controlled demo previews.
   */
  defaultCode?: string;
  /**
   * Callback fired whenever the end-user saves or rotates their Anti-Phishing Code.
   */
  onConfigured?: (payload: ShieldCodeWidgetConfiguredPayload) => void;
}

