/**
 * Internal UI rendered inside the isolated ShadowRoot.
 */
function ShadowInnerWidget({
  clientSessionToken,
  apiBaseUrl = "",
  defaultCode = "Bachir34",
  onConfigured,
}: ShieldCodeWidgetProps) {
  const [code, setCode] = useState(defaultCode);
  const [isEnabled, setIsEnabled] = useState(true);
  const [maskedCode, setMaskedCode] = useState<string | null>("Bac***");
  const [companyName, setCompanyName] = useState("FinanzaBank");
  const [isSaving, setIsSaving] = useState(false);
  const [feedback, setFeedback] = useState<{
    type: "success" | "error";
    text: string;
  } | null>(null);

  const endpoint = `${apiBaseUrl.replace(/\/+$/, "")}/api/v1/widget/configure`;

  useEffect(() => {
    if (!clientSessionToken) return;
    let cancelled = false;

    async function loadInitialStatus() {
      try {
        const res = await fetch(endpoint, {
          method: "GET",
          headers: {
            Authorization: `Bearer ${clientSessionToken}`,
          },
        });
        const data = await res.json();
        if (!cancelled && res.ok) {
          setIsEnabled(Boolean(data.is_enabled));
          setMaskedCode(data.masked_code || null);
          if (data.security_code_preview) {
            setCode(data.security_code_preview);
          }
          if (data.company_name) {
            setCompanyName(data.company_name);
          }
        }
      } catch {
        // Keep default fallback in offline preview
      }
    }

    loadInitialStatus();
    return () => {
      cancelled = true;
    };
  }, [clientSessionToken, endpoint]);

  const handleGenerateRandom = () => {
    const samples = ["Bachir34", "ApexVault9", "SafeBank77", "Falcon88X"];
    const pick = samples[Math.floor(Math.random() * samples.length)];
    setCode(pick);
    setFeedback(null);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const trimmed = code.trim();

    if (!/^[A-Za-z0-9_\-\u0600-\u06FF]{4,20}$/.test(trimmed)) {
      setFeedback({
        type: "error",
        text: "Code must be 4–20 alphanumeric characters (no spaces or special symbols).",
      });
      return;
    }

    setIsSaving(true);
    setFeedback(null);

    try {
      const res = await fetch(endpoint, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${clientSessionToken}`,
        },
        body: JSON.stringify({
          anti_phishing_code: trimmed,
        }),
      });
      const data = await res.json();

      if (!res.ok) {
        setFeedback({
          type: "error",
          text: data.message || "Failed to update Anti-Phishing Code.",
        });
        return;
      }

      setIsEnabled(true);
      setMaskedCode(data.masked_code);
      setFeedback({
        type: "success",
        text: `Saved! Every official SMS/Email from ${
          data.company_name || companyName
        } will now include [${data.security_code}].`,
      });

      if (onConfigured) {
        onConfigured(data);
      }
    } catch {
      setFeedback({
        type: "error",
        text: "Network error while connecting to ShieldCode Vault API.",
      });
    } finally {
      setIsSaving(false);
    }
  };

  const shortTokenPreview =
    clientSessionToken.length > 24
      ? `${clientSessionToken.slice(0, 14)}...${clientSessionToken.slice(-6)}`
      : clientSessionToken;

  return (
    <>
      <style>{SHADOW_DOM_ENCAPSULATED_CSS}</style>
      <div className="sc-widget-shell" part="shieldcode-widget">
        <div className="sc-top-row">
          <div className="sc-brand-group">
            <div className="sc-shield-badge">🛡️</div>
            <div>
              <h4 className="sc-heading">
                ShieldCode™ Drop-In Anti-Phishing Widget
              </h4>
              <p className="sc-subtext">
                Isolated Shadow DOM • Direct TLS to ShieldCode Vault ({companyName})
              </p>
            </div>
          </div>

          <span
            className={`sc-status-pill ${
              isEnabled ? "sc-status-enabled" : "sc-status-pending"
            }`}
          >
            <span className="sc-status-dot" />
            {isEnabled
              ? `Active (${maskedCode || "Set"})`
              : "Unconfigured"}
          </span>
        </div>

        <form onSubmit={handleSubmit} className="sc-form-row">
          <div className="sc-input-container">
            <input
              type="text"
              value={code}
              maxLength={20}
              onChange={(e) => {
                setCode(e.target.value);
                setFeedback(null);
              }}
              placeholder="Enter 4–20 char code (e.g. Bachir34)"
              className="sc-code-input"
              required
            />
            <div className="sc-input-actions">
              <span className="sc-char-count">{code.length}/20</span>
              <button
                type="button"
                onClick={handleGenerateRandom}
                className="sc-auto-btn"
              >
                Auto
              </button>
            </div>
          </div>

          <button
            type="submit"
            disabled={isSaving || code.trim().length < 4}
            className="sc-save-button"
          >
            {isSaving ? (
              <>
                <span className="sc-spinner" />
                Encrypting...
              </>
            ) : (
              "Save ShieldCode"
            )}
          </button>
        </form>

        {feedback && (
          <div
            className={`sc-alert ${
              feedback.type === "success"
                ? "sc-alert-success"
                : "sc-alert-error"
            }`}
          >
            {feedback.text}
          </div>
        )}

        <div className="sc-meta-bar">
          <span>
            🔒 Direct Endpoint: <code>POST /api/v1/widget/configure</code>
          </span>
          <span className="sc-jwt-tag" title={clientSessionToken}>
            JWT: {shortTokenPreview}
          </span>
        </div>
      </div>
    </>
  );
}

/**
 * Public `<ShieldCodeWidget clientSessionToken="ey..." />` Drop-In Component.
 * Mounts its UI inside a native browser Shadow DOM (`attachShadow({ mode: "open" })`)
 * so that the host Bank's CSS never collides with the widget's styling.
 */
export function ShieldCodeWidget(props: ShieldCodeWidgetProps) {
  const hostRef = useRef<HTMLDivElement | null>(null);
  const shadowRootRef = useRef<Root | null>(null);

  useEffect(() => {
    const hostEl = hostRef.current;
    if (!hostEl) return;

    if (!shadowRootRef.current) {
      const shadow =
        hostEl.shadowRoot || hostEl.attachShadow({ mode: "open" });
      const mountPoint = document.createElement("div");
      shadow.innerHTML = "";
      shadow.appendChild(mountPoint);
      shadowRootRef.current = createRoot(mountPoint);
    }

    shadowRootRef.current.render(<ShadowInnerWidget {...props} />);
  }, [props]);

  return <div ref={hostRef} data-shieldcode-shadow-host="true" />;
}
